CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS products(id text PRIMARY KEY, name text NOT NULL, sale_start timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS inventory(product_id text PRIMARY KEY REFERENCES products(id), available integer NOT NULL CHECK(available>=0));
CREATE TABLE IF NOT EXISTS checkout_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL, idempotency_key text NOT NULL, request_fingerprint text NOT NULL, product_id text NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity=1), status text NOT NULL CHECK(status IN ('QUEUED','PROCESSING','CONFIRMED','SOLD_OUT','FAILED')), processing_token text, lease_until timestamptz, terminal_result text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS checkout_status_idx ON checkout_requests(status); CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), checkout_request_id uuid NOT NULL UNIQUE REFERENCES checkout_requests(id), product_id text NOT NULL, quantity integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_events(id bigserial PRIMARY KEY, event_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, published_at timestamptz, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS outbox_pending_idx ON outbox_events(published_at) WHERE published_at IS NULL;
ALTER TABLE checkout_requests ADD COLUMN IF NOT EXISTS status_version bigint NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS sale_config(id boolean PRIMARY KEY DEFAULT true, sale_start timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'UTC');
INSERT INTO sale_config(id,sale_start,timezone) VALUES(true,now(),'UTC') ON CONFLICT (id) DO NOTHING;
INSERT INTO products(id,name,sale_start) VALUES('phone-500','Flash Sale Smartphone',now()) ON CONFLICT DO NOTHING; INSERT INTO inventory(product_id,available) VALUES('phone-500',500) ON CONFLICT DO NOTHING;
